import{_ as o,o as t,c as d,ag as a}from"./chunks/framework.NIGIbcGl.js";const p=JSON.parse('{"title":"BlockSeat Bookings Guide (Wholesale)","description":"","frontmatter":{},"headers":[],"relativePath":"customer/blockseat-bookings/index.md","filePath":"customer/blockseat-bookings/index.md"}'),n={name:"customer/blockseat-bookings/index.md"};function s(i,e,c,r,l,g){return t(),d("div",null,[...e[0]||(e[0]=[a('<h1 id="blockseat-bookings-guide-wholesale" tabindex="-1">BlockSeat Bookings Guide (Wholesale) <a class="header-anchor" href="#blockseat-bookings-guide-wholesale" aria-label="Permalink to &quot;BlockSeat Bookings Guide (Wholesale)&quot;">​</a></h1><p>BlockSeat bookings are the <strong>wholesale</strong> flow for groups of <strong>≥11 seated passengers</strong> (adults + children; infants are lap, configurable via <code>BLOCKSEAT_MIN_PASSENGERS</code>). They ride the <strong>standard <code>ota/*</code> booking flow</strong> — a real supplier <strong>GROUP</strong> reservation, payment → <code>CONFIRMED</code> → async ticketing → <code>TICKETED</code>, with passenger names added later (supplier-native). There is <strong>no manifest step and no auto-confirm</strong> — BlockSeat does <strong>not</strong> use the custom-booking lifecycle.</p><p>They differ from a regular <code>ota/*</code> booking only in:</p><ul><li><strong>Pricing.</strong> Priced supplier price <strong>− BlockSeat route reducer</strong> for <strong>every</strong> cabin class, STANDARD fare (no strikethrough). The booked price equals the <a href="/ahlaan-train-docs/customer/blockseat-ota/">BlockSeat OTA</a> quote exactly.</li><li><strong>Variant scope.</strong> BlockSeat rows are the same <code>Booking</code> table with <code>bookingVariant = BLOCKSEAT</code>. BlockSeat endpoints only ever see BlockSeat bookings; <code>ota/*</code> endpoints only see standard bookings (a cross-variant id/code returns <code>404</code>).</li></ul><p>Everything else — request bodies, GROUP reservation, status machine, payment (Xendit / wallet), cancellation + refund, ticket download — is identical to <a href="/ahlaan-train-docs/customer/booking-management/">OTA Bookings</a>.</p><blockquote><p><strong>Host.</strong> Served on <code>blockseat.ahlaan.co.id</code>.</p></blockquote><hr><h2 id="flow" tabindex="-1">Flow <a class="header-anchor" href="#flow" aria-label="Permalink to &quot;Flow&quot;">​</a></h2><ol><li><strong>Quote</strong> via <code>POST /api/v1/blockseat-ota/book/calculate</code> (≥11 enforced).</li><li><strong>Book</strong> via <code>POST /api/v1/blockseat-bookings/book</code> with <code>passengerQuantities</code> (GROUP — names not required yet). A real supplier reservation is held; status <code>PENDING</code>.</li><li><strong>Pay</strong> (Xendit link or wallet) → webhook → <code>CONFIRMED</code>.</li><li><strong>Add passenger names</strong> via <code>PATCH /:id/modify</code> (Type 4) within the supplier&#39;s update-travellers deadline.</li><li><strong>Ticketing</strong> runs (async / admin retry) → <code>TICKETED</code>; download tickets.</li></ol><p>No manifest upload, no admin manifest review, no auto-confirm-on-manifest.</p><h2 id="endpoints" tabindex="-1">Endpoints <a class="header-anchor" href="#endpoints" aria-label="Permalink to &quot;Endpoints&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Method</th><th>Path</th><th>Notes</th></tr></thead><tbody><tr><td><code>POST</code></td><td><code>/api/v1/blockseat-bookings/book</code></td><td>Create a wholesale GROUP booking (guest supported via contact person). Requires <code>passengerQuantities</code> (≥11 seated). Real supplier hold; priced supplier − reducer.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/blockseat-bookings</code></td><td>List my BlockSeat bookings (JWT).</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/blockseat-bookings/:id</code></td><td>Get by id.</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/blockseat-bookings/code/:bookingCode</code></td><td>Get by booking code.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/blockseat-bookings/:id/cancel</code></td><td>Cancel + refund (same as OTA).</td></tr><tr><td><code>PATCH</code></td><td><code>/api/v1/blockseat-bookings/:id/passengers</code></td><td>Add/update GROUP passenger names.</td></tr><tr><td><code>PATCH</code></td><td><code>/api/v1/blockseat-bookings/:id/modify</code></td><td>Modify (Type 4 add names, Type 9 contact, Type 40 info, Type 10 cancel segment).</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/blockseat-bookings/:id/tickets</code></td><td>Download all tickets (ZIP, public).</td></tr><tr><td><code>GET</code></td><td><code>/api/v1/blockseat-bookings/:id/ticket</code></td><td>Download a specific ticket (PDF, public).</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/blockseat-bookings/:id/resend-confirmation-email</code></td><td>Resend ticket confirmation email.</td></tr><tr><td><code>POST</code></td><td><code>/api/v1/blockseat-bookings/:id/resend-cancellation-email</code></td><td>Resend cancellation email.</td></tr></tbody></table><p>Status lifecycle, payment, and refunds follow the standard <a href="/ahlaan-train-docs/customer/booking-management/">OTA booking</a> model (<code>PENDING → CONFIRMED → TICKETING_IN_PROGRESS → TICKETED</code>; <code>CANCELLED</code> / <code>EXPIRED</code> / <code>FAILED</code> terminal).</p>',13)])])}const b=o(n,[["render",s]]);export{p as __pageData,b as default};
